def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: A serialisable representation of the point (dict or tuple)
    """
    # Handle None explicitly
    if value is None:
        return None

    # If the value is already a tuple/list of coordinates, just normalise it
    if isinstance(value, (tuple, list)):
        if len(value) in (2, 3):
            try:
                return tuple(value)
            except Exception as exc:
                raise ValueError(f"Failed to convert point tuple to tuple: {exc}") from exc
        else:
            raise ValueError("Point tuple/list must contain 2 or 3 elements")

    # Try to extract coordinate attributes from an object
    try:
        # Basic check for required attributes
        if not hasattr(value, "x") or not hasattr(value, "y"):
            raise TypeError("Object does not have required 'x' and 'y' attributes")

        point_dict = {"x": getattr(value, "x"), "y": getattr(value, "y")}

        # Optional z coordinate
        if hasattr(value, "z"):
            point_dict["z"] = getattr(value, "z")

        return point_dict
    except AttributeError as exc:
        raise TypeError(f"Failed to access point attributes: {exc}") from exc
    except Exception as exc:
        raise ValueError(f"Unexpected error while dehydrating point: {exc}") from exc

