def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        return list(self.values())

    # Prepare a list of all values for index-based access
    all_values = list(self.values())
    result = []

    for k in keys:
        # Handle integer indices
        if isinstance(k, int):
            # Support negative indices
            if -len(all_values) <= k < len(all_values):
                result.append(all_values[k])
            else:
                # Index out of range – ignore or raise? Here we ignore
                continue
        # Handle string keys
        elif isinstance(k, str):
            if k in self:
                result.append(self[k])
            else:
                # Key not present – ignore
                continue
        else:
            # Unsupported key type
            raise TypeError(f"Unsupported key type: {type(k).__name__}")

    return result

