def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine underlying data structures
    if hasattr(self, "_data") and hasattr(self, "_keys"):
        data = self._data
        keys_list = self._keys
    elif hasattr(self, "data") and hasattr(self, "keys"):
        data = self.data
        keys_list = self.keys
    else:
        # Fallback: use public attributes as keys
        keys_list = [k for k in self.__dict__ if not k.startswith("_")]
        data = [getattr(self, k) for k in keys_list]

    if not keys:
        return dict(zip(keys_list, data))

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(data):
                raise IndexError(
                    f"Index {key} out of bounds for record of length {len(data)}"
                )
            result[keys_list[key]] = data[key]
        else:
            # treat as key
            if key in keys_list:
                idx = keys_list.index(key)
                result[key] = data[idx]
            else:
                result[key] = None
    return result

