def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure the object has a mutable byte sequence
    if not hasattr(self, "data"):
        raise AttributeError("The object does not have a 'data' attribute.")
    if not isinstance(self.data, (bytearray, list)):
        raise TypeError("The 'data' attribute must be a bytearray or list of ints.")
    # Ensure there are at least two bytes to pop
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop a 16‑bit integer.")
    # Extract the last two bytes
    try:
        # For bytearray, slice returns a bytearray; convert to bytes for int conversion
        last_two = bytes(self.data[-2:])
    except Exception as exc:
        raise ValueError(f"Error extracting last two bytes: {exc}") from exc
    # Remove the last two bytes from the data
    del self.data[-2:]
    # Convert to a big‑endian unsigned 16‑bit integer
    return int.from_bytes(last_two, byteorder="big")

