def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")
    try:
        from shapely.geometry import Point
    except Exception as e:
        raise ImportError("shapely.geometry.Point is required") from e

    # Build class dictionary
    class_dict = {}
    for f in fields:
        if not isinstance(f, str):
            raise TypeError("field names must be strings")
        class_dict[f] = None
    class_dict['SRID_MAP'] = srid_map

    def __init__(self, x, y, z=None, **kwargs):
        Point.__init__(self, x, y, z)
        for key, value in kwargs.items():
            if key in fields:
                setattr(self, key, value)
            else:
                raise AttributeError(f"Unknown field {key}")

    class_dict['__init__'] = __init__
    new_cls = type(name, (Point,), class_dict)
    return new_cls

