def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time value")
    if not isinstance(maxsize, (int, type(None))) or (isinstance(maxsize, int) and maxsize < 0):
        raise ValueError("maxsize must be a non-negative integer or None")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise ValueError("ttl must be a non-negative number")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    from functools import wraps
    from collections import OrderedDict

    def decorating_function(user_function):
        if not callable(user_function):
            raise TypeError("ttl_cache can only be applied to callable objects")

        cache = OrderedDict()

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            # Build a hashable key from arguments
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types of positional arguments
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))

            now = timer()
            if key in cache:
                result, timestamp = cache[key]
                if now - timestamp < ttl:
                    # Move to the end to mark as recently used
                    cache.move_to_end(key)
                    return result
                else:
                    # Expired entry
                    del cache[key]

            # Compute the result and store it
            result = user_function(*args, **kwargs)
            cache[key] = (result, now)
            cache.move_to_end(key)

            # Enforce maxsize limit
            if maxsize is not None and len(cache) > maxsize:
                cache.popitem(last=False)

            return result

        # Optional helper to clear the cache
        def cache_clear():
            cache.clear()

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

