def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non‑negative integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorating_function(user_function):
        cache = {}
        order_counter = 0

        def wrapper(*args, **kwargs):
            nonlocal order_counter
            # Build a hashable key
            try:
                if typed:
                    key = (
                        args,
                        tuple(sorted(kwargs.items())),
                        tuple(type(arg) for arg in args),
                        tuple(type(v) for v in kwargs.values()),
                    )
                else:
                    key = (args, tuple(sorted(kwargs.items())))
            except Exception:
                # If the key cannot be built (e.g., unhashable arguments),
                # fall back to calling the function without caching.
                return user_function(*args, **kwargs)

            if key in cache:
                value, count, order = cache[key]
                cache[key] = (value, count + 1, order)
                return value

            # Compute the result
            result = user_function(*args, **kwargs)

            # Add to cache if caching is enabled
            if maxsize > 0:
                if len(cache) >= maxsize:
                    # Find the least frequently used items
                    min_count = min(v[1] for v in cache.values())
                    candidates = [k for k, v in cache.items() if v[1] == min_count]
                    # Evict the oldest among the candidates
                    evict_key = min(candidates, key=lambda k: cache[k][2])
                    del cache[evict_key]
                order_counter += 1
                cache[key] = (result, 1, order_counter)

            return result

        return wrapper

    return decorating_function

