def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not hasattr(classes, "__iter__"):
        raise TypeError("classes must be an iterable of class objects")
    minimal = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class object, got {type(cls).__name__}")
        # Remove any existing minimal class that is a superclass of cls
        minimal = [m for m in minimal if not issubclass(cls, m)]
        # If cls is a subclass of any remaining minimal class, skip it
        if any(issubclass(cls, m) for m in minimal):
            continue
        minimal.append(cls)
    return minimal

