def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Ensure we have an iterable sequence
    try:
        iter(sequence)
    except TypeError:
        raise TypeError(f"_normalizeargs expects an iterable, got {type(sequence).__name__}")

    for arg in sequence:
        # Skip None values
        if arg is None:
            continue

        # If the argument is a tuple/list/set, recurse into it
        if isinstance(arg, (list, set, tuple)):
            _normalizeargs(arg, output)
            continue

        # If the argument is a Declaration (or any object that exposes an
        # ``interfaces`` attribute), expand it
        if hasattr(arg, "interfaces"):
            try:
                for iface in getattr(arg, "interfaces"):
                    output.append(iface)
            except Exception as exc:
                raise ValueError(f"Failed to expand interfaces from {arg!r}: {exc}") from exc
            continue

        # Otherwise treat the argument as an individual interface or implements spec
        output.append(arg)

    return output

