            bins = {}
        self.bins = bins
    else:
        # No initial value provided; use make_bins if available
        make_bins = getattr(self, 'make_bins', None)
        if callable(make_bins):
            self.bins = make_bins()
        else:
            # Fallback to an empty dict if make_bins is not defined
            self.bins = {}

