          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Ensure separator is a string
    if separator is None:
        separator = ","
    else:
        separator = str(separator)

    lines = []

    if header is not None:
        lines.append(str(header))

    # Try to iterate over self; fall back to a 'points' attribute if present
    try:
        points_iter = iter(self)
    except TypeError:
        points_iter = getattr(self, "points", [])

    for point in points_iter:
        if point is None:
            continue

        # Handle point as a tuple/list of (coords, value)
        if isinstance(point, (list, tuple)) and len(point) == 2:
            coords, value = point
        else:
            coords = getattr(point, "coords", None)
            value = getattr(point, "value", None)

        # Convert coords to iterable
        if coords is None:
            coords_iter = []
        else:
            try:
                coords_iter = iter(coords)
            except TypeError:
                coords_iter = [coords]

        # Convert value to iterable
        if value is None:
            value_iter = []
        else:
            try:
                value_iter = iter(value)
            except TypeError:
                value_iter = [value]

        parts = [str(c) for c in coords_iter] + [str(v) for v in value_iter]
        lines.append(separator.join(parts))

    return "\n".join(lines)

