def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Preferred: a dedicated dictionary mapping coordinate names to index lists
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        return list(self._err_indices.get(coord_name, []))

    # Fallback: a generic `errors` attribute that may be a list of dicts or tuples
    if hasattr(self, "errors") and isinstance(self.errors, list):
        indices = []
        for e in self.errors:
            if isinstance(e, dict):
                if e.get("coord") == coord_name:
                    idx = e.get("index")
                    if idx is not None:
                        indices.append(idx)
            elif isinstance(e, tuple) and len(e) >= 2:
                if e[0] == coord_name:
                    indices.append(e[1])
        return indices

    # If no known error structure is present, return an empty list
    return []

