def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure the histogram has the necessary attributes
    if not hasattr(self, "edges") or not hasattr(self, "data"):
        raise AttributeError("Histogram object must have 'edges' and 'data' attributes.")
    try:
        # Find the bin index for the coordinate
        idx = np.searchsorted(self.edges, coord, side="right") - 1
    except Exception:
        # If coord is not comparable to edges, ignore
        return
    # Ignore coordinates outside the histogram range
    if idx < 0 or idx >= len(self.data):
        return
    # Increment the bin count by the given weight
    try:
        self.data[idx] += weight
    except Exception:
        # If data is not a mutable numeric type, ignore
        pass

