    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    # Ensure the key is a string
    if not isinstance(key, str):
        raise ValidationError("Key must be a string")

    # Retrieve the regular expression pattern used for validation
    try:
        pattern = KEY_REGEX
    except NameError:
        raise ValidationError("KEY_REGEX is not defined for key validation")

    # If the pattern is a string, compile it (assuming re is available)
    if isinstance(pattern, str):
        try:
            import re
            pattern = re.compile(pattern)
        except Exception as exc:
            raise ValidationError(f"Failed to compile KEY_REGEX: {exc}")

    # Perform the match
    if not pattern.match(key):
        raise ValidationError(f"Key '{key}' does not match required pattern")

    return True

