def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Retrieve the manifest list from the application spec
        spec = getattr(app, "spec", None)
        if spec is None:
            return
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            return

        # Iterate over each resource in the manifest
        for resource in manifest:
            # Skip non-dict entries
            if not isinstance(resource, dict):
                continue

            # Skip resources that already have a custom observer schema
            if "observer_schema" in resource:
                continue

            # Build a minimal default observer schema
            kind = resource.get("kind")
            if not kind:
                # If the kind is missing, we cannot generate a meaningful schema
                continue

            metadata = resource.get("metadata", {})
            name = metadata.get("name")

            default_schema = {"kind": kind}
            if name:
                default_schema["metadata"] = {"name": name}

            # Attach the default schema to the resource
            resource["observer_schema"] = default_schema

    except Exception as exc:
        # Re-raise the exception to surface any unexpected errors
        raise exc

