def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve the root path
        if path is None:
            return False

        # If path is a pyfs root-like object, try to use its methods
        if hasattr(path, "exists") and hasattr(path, "is_dir"):
            root = path
            # Check existence and directory
            if not root.exists() or not root.is_dir():
                return False
            # Helper to read a file's text
            def read_text(file_path):
                try:
                    with file_path.open("r") as f:
                        return f.read().strip()
                except Exception:
                    return None
            # Check for .ocfl_version file
            version_file = root.joinpath(".ocfl_version")
            if not version_file.exists():
                return False
            version_text = read_text(version_file)
            if not version_text or not version_text.isdigit():
                return False
            # Check for .ocfl_root directory
            ocfl_root_dir = root.joinpath(".ocfl_root")
            if not ocfl_root_dir.exists() or not ocfl_root_dir.is_dir():
                return False
            # Ensure at least one object directory inside .ocfl_root
            try:
                if not any(ocfl_root_dir.iterdir()):
                    return False
            except Exception:
                return False
            return True

        # Otherwise treat path as a filesystem path string or Path object
        from pathlib import Path
        root = Path(path)
        if not root.exists() or not root.is_dir():
            return False

        # Check for .ocfl_version file
        version_file = root / ".ocfl_version"
        if not version_file.is_file():
            return False
        try:
            version_text = version_file.read_text().strip()
        except Exception:
            return False
        if not version_text.isdigit():
            return False

        # Check for .ocfl_root directory
        ocfl_root_dir = root / ".ocfl_root"
        if not ocfl_root_dir.is_dir():
            return False
        # Ensure at least one object directory inside .ocfl_root
        try:
            if not any(ocfl_root_dir.iterdir()):
                return False
        except Exception:
            return False

        return True
    except Exception:
        # Any unexpected error results in validation failure
        return False

