def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Validate manifest_files
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise TypeError("manifest_files must be an iterable of file names")

    # Validate fixity input
    if fixity is None:
        raise ValueError("fixity cannot be None")

    # Determine the form of the fixity block
    if isinstance(fixity, dict):
        # Treat as mapping: file -> hash (or file -> {hash, algorithm, ...})
        entries = []
        for file_name, value in fixity.items():
            if not isinstance(file_name, str):
                raise ValueError(f"File name in fixity mapping must be a string, got {type(file_name)}")
            if isinstance(value, dict):
                entry = value.copy()
                entry['file'] = file_name
                entries.append(entry)
            else:
                # Assume value is the hash string
                entries.append({'file': file_name, 'hash': value})
    elif isinstance(fixity, list):
        entries = fixity
    else:
        raise TypeError("fixity must be a dict or a list of entries")

    seen_files = set()
    for idx, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry at index {idx} must be a dict, got {type(entry)}")

        # Required keys
        if 'file' not in entry:
            raise ValueError(f"Fixity entry at index {idx} missing required 'file' key")
        if 'hash' not in entry:
            raise ValueError(f"Fixity entry at index {idx} missing required 'hash' key")

        file_name = entry['file']
        if not isinstance(file_name, str):
            raise ValueError(f"File name in entry at index {idx} must be a string, got {type(file_name)}")

        if file_name in seen_files:
            raise ValueError(f"Duplicate fixity entry for file '{file_name}'")
        seen_files.add(file_name)

        if file_name not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{file_name}' not present in manifest")

        # Validate hash
        h = entry['hash']
        if not isinstance(h, str):
            raise ValueError(f"Hash for file '{file_name}' must be a string, got {type(h)}")
        if not all(c in '0123456789abcdefABCDEF' for c in h):
            raise ValueError(f"Hash for file '{file_name}' is not a valid hexadecimal string")

        # Optional algorithm check
        if 'algorithm' in entry:
            alg = entry['algorithm']
            if not isinstance(alg, str):
                raise ValueError(f"Algorithm for file '{file_name}' must be a string, got {type(alg)}")

    # All checks passed
    return True

