def files_list(path):
    """Return the files in `path`"""
    import os
    # Accept string or os.PathLike objects
    if hasattr(path, "__fspath__"):
        path = os.fspath(path)
    if not isinstance(path, str):
        raise TypeError(f"path must be a string or PathLike object, got {type(path).__name__}")
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")
    try:
        entries = os.listdir(path)
    except OSError as exc:
        raise OSError(f"Error listing directory {path!r}: {exc}") from exc
    files = [f for f in entries if os.path.isfile(os.path.join(path, f))]
    return files

