def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non-negative integer")
    try:
        lines = []
        prefix = '  ' * indent
        cls_name = self.__class__.__name__
        id_val = getattr(self, 'id', None)
        header = f"{prefix}{cls_name}"
        if id_val is not None:
            header += f" (id={id_val})"
        lines.append(header)
        # Show non-child attributes
        for key, val in getattr(self, '__dict__', {}).items():
            if key in ('children', 'child', 'elements'):
                continue
            if isinstance(val, (list, tuple)):
                # skip if likely children
                continue
            lines.append(f"{prefix}  {key}={val!r}")
        # Get children
        children = getattr(self, 'children', None)
        if children is None:
            try:
                children = list(self)
            except TypeError:
                children = []
        for child in children:
            if hasattr(child, 'pretty'):
                lines.append(child.pretty(indent + 1, debug))
            else:
                lines.append(f"{prefix}  {repr(child)}")
        return '\n'.join(lines)
    except Exception as e:
        if debug:
            raise
        return f"<Error pretty printing {self.__class__.__name__}: {e}>"

