def get_versions():
    """Get version information or return default if unable to do so."""
    import sys
    import platform
    try:
        # Python 3.8+ provides importlib.metadata
        from importlib.metadata import version, PackageNotFoundError
        try:
            # Attempt to get the version of the current package
            pkg_name = __package__ or __name__
            # If the module is part of a package, __package__ will be the package name
            # If not, __name__ may be the module name; we try both
            try:
