    """Render the given version pieces into the requested style."""
    # Default to plain text if style is not provided
    if style is None:
        style = 'plain'
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    # Handle None pieces
    if pieces is None:
        return ''

    # If a single string is provided, treat it as a single-element list
    if isinstance(pieces, str):
        pieces = [pieces]

    # Ensure pieces is iterable
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of strings or objects")

    # Convert each piece to a string, skipping None values
    rendered_pieces = []
    for p in pieces:
        if p is None:
