        rendered_pieces.append(str(p))

    # Render according to the requested style
    if style == 'plain':
        return ''.join(rendered_pieces)
    elif style == 'html':
        # Wrap each piece in a <span> tag
        return ''.join(f'<span>{p}</span>' for p in rendered_pieces)
