def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _traverse(obj):
        nonlocal num_objects, good_objects
        if obj is None:
            return
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    res = obj.validate()
                    if res is False:
                        valid = False
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: validation failed for {obj}: {e}")

        if check_digests and valid:
            try:
                if hasattr(obj, 'check_digest'):
                    res = obj.check_digest()
                    if res is False:
                        valid = False
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: digest check failed for {obj}: {e}")

        if valid:
            good_objects += 1

        # Recurse into children if iterable
        try:
            for child in obj:
                _traverse(child)
        except TypeError:
            # obj is not iterable
            pass

    _traverse(self)
    return num_objects, good_objects

