def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Import modules locally to avoid top‑level imports
    import os
    from pathlib import Path

    # Resolve the root path
    if not hasattr(self, "path") or self.path is None:
        raise ValueError("The instance must have a 'path' attribute pointing to the desired OCFL root location.")
    root = Path(self.path).expanduser().resolve()

    # Check if the root already exists
    if root.exists():
        if root.is_dir():
            raise FileExistsError(f"OCFL root already exists at {root}")
        else:
            raise FileExistsError(f"A non‑directory file already exists at {root}")

    try:
        # Create the root directory
        root.mkdir(parents=True, exist_ok=False)

        # Create the .ocfl_root file with minimal metadata
        ocfl_file = root / ".ocfl_root"
        ocfl_file.write_text("ocfl_version: 1.0\n")

        # Create the objects directory
        objects_dir = root / "objects"
        objects_dir.mkdir()

        # Store the resolved root path on the instance for later use
        self.root_path = root
        self.objects_path = objects_dir

    except OSError as exc:
        # Clean up partially created structure if an error occurs
        if root.exists() and root.is_dir():
            try:
                # Remove any created files/directories
                for child in root.iterdir():
                    if child.is_file():
                        child.unlink()
                    else:
                        child.rmdir()
                root.rmdir()
            except Exception:
                pass
        raise RuntimeError(f"Failed to initialize OCFL root at {root}: {exc}") from exc

