def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    v = version.strip()
    if not v:
        raise ValueError("empty version string")
    # If the version is a single numeric component
    if v.isdigit():
        width = len(v)
        new_num = int(v) + 1
        return str(new_num).zfill(width)
    # Handle dotted versions (e.g., "1.2", "001.002")
    parts = v.split('.')
    # Find the last numeric part to increment
    for i in range(len(parts) - 1, -1, -1):
        if parts[i].isdigit():
            width = len(parts[i])
            new_num = int(parts[i]) + 1
            parts[i] = str(new_num).zfill(width)
            return '.'.join(parts)
    # If no numeric part found, raise an error
    raise ValueError("version string does not contain a numeric component")

