def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Prepare storage for differences
    self.different_digests = {}

    # Load root inventory
    try:
        root_inventory_path = os.path.join(self.root_dir, "inventory.xml")
    except AttributeError:
        raise AttributeError("The object must have a 'root_dir' attribute pointing to the root directory")

    if not os.path.exists(root_inventory_path):
        raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}")

    try:
        root_tree = ET.parse(root_inventory_path)
        root_root = root_tree.getroot()
    except Exception as exc:
        raise ValueError(f"Failed to parse root inventory XML: {exc}")

    # Build a mapping of file name -> digest from the root inventory
    root_digests = {}
    for file_elem in root_root.findall(".//file"):
        name = file_elem.get("name")
        digest = file_elem.get("digest")
        if name and digest:
            root_digests[name] = digest

    # Keep track of all files seen so far to ensure inventories are cumulative
    previous_files = set()

    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(vdir, "inventory.xml")
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Inventory missing in version directory '{vdir}'")

        try:
            tree = ET.parse(inv_path)
            inv_root = tree.getroot()
        except Exception as exc:
            raise ValueError(f"Failed to parse inventory XML in '{vdir}': {exc}")

        current_files = set()
        for file_elem in inv_root.findall(".//file"):
            name = file_elem.get("name")
            digest = file_elem.get("digest")
            if not name or not digest:
                continue  # skip malformed entries
            current_files.add(name)

            # Compare with root digest if available
            root_digest = root_digests.get(name)
            if root_digest and root_digest != digest:
                self.different_digests.setdefault(name, []).append((root_digest, digest))

        # Ensure the current inventory contains all files from previous versions
        if not previous_files.issubset(current_files):
            missing = previous_files - current_files
            raise ValueError(
                f"Version {idx} inventory missing files from previous versions: {sorted(missing)}"
            )

        previous_files = current_files

    # If we reach here, all inventories are valid and cumulative
    return True

