def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate input
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return params

    # Normalise bug_ids to a list of strings
    if isinstance(bug_ids, (list, tuple, set)):
        ids = [str(b) for b in bug_ids]
    else:
        # Assume a single id or a comma‑separated string
        ids = [str(bug_ids)]
        if ',' in ids[0]:
            ids = [s.strip() for s in ids[0].split(',') if s.strip()]

    # Merge with existing 'ids' entry if present
    if 'ids' in params:
        existing = params['ids']
        if isinstance(existing, str):
            existing_ids = [s.strip() for s in existing.split(',') if s.strip()]
        elif isinstance(existing, (list, tuple, set)):
            existing_ids = [str(e) for e in existing]
        else:
            existing_ids = [str(existing)]
        merged = sorted(set(existing_ids) | set(ids), key=lambda x: int(x) if x.isdigit() else x)
        params['ids'] = ','.join(merged)
    else:
        params['ids'] = ','.join(ids)

    return params

