def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    # Validate that the object behaves like an ArgumentParser
    try:
        actions = getattr(parser, "_actions", None)
        if actions is None:
            raise AttributeError
    except Exception:
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        try:
            opt_strings = getattr(action, "option_strings", [])
        except Exception:
            continue
        for opt in opt_strings:
            if isinstance(opt, str) and opt.startswith("-"):
                flags.append(opt)

    # Preserve order while removing duplicates
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)

    return " ".join(unique_flags)

