def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    import re
    try:
        from urllib.parse import quote
    except Exception:
        # Fallback if urllib.parse is unavailable
        def quote(s, safe=''):
            return s

    # Pattern to find placeholders like {key}
    pattern = re.compile(r'\{([^{}]+)\}')

    def _repl(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"Missing URL argument: {key}")
        value = url_args[key]
        # Convert to string and percent‑encode
        value_str = str(value)
        return quote(value_str, safe='')

    try:
        return pattern.sub(_repl, url)
    except re.error as e:
        raise ValueError(f"Invalid URL pattern: {e}") from None
    except Exception as e:
        raise RuntimeError(f"Error replacing URL arguments: {e}") from None

