def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True

    # Only strings can represent a textual None
    if isinstance(val, str):
        # Strip whitespace and compare case-insensitively
        stripped = val.strip()
        # Common textual representations of None
        none_values = {"none", "null", "nan", "na", "n/a"}
        if stripped == "" or stripped.lower() in none_values:
            return True

    # All other cases are not considered None
    return False

