def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip().lower()
    if freq == "always":
        return None

    import re
    match = re.match(r'^\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*$', freq)
    if not match:
        raise ValueError(f"Unable to parse frequency: {frequency!r}")

    number = float(match.group(1))
    unit = match.group(2)

    # Mapping of unit strings to timedelta keyword arguments
    unit_map = {
        'day': 'days', 'days': 'days', 'd': 'days',
        'week': 'weeks', 'weeks': 'weeks', 'w': 'weeks',
        'hour': 'hours', 'hours': 'hours', 'h': 'hours',
        'minute': 'minutes', 'minutes': 'minutes', 'min': 'minutes', 'm': 'minutes',
        'second': 'seconds', 'seconds': 'seconds', 's': 'seconds',
        'millisecond': 'milliseconds', 'milliseconds': 'milliseconds', 'ms': 'milliseconds',
        'microsecond': 'microseconds', 'microseconds': 'microseconds', 'us': 'microseconds',
        'month': 'days', 'months': 'days',
        'year': 'days', 'years': 'days',
    }

    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: {unit!r}")

    keyword = unit_map[unit]

    # Handle months and years as days
    if unit in ('month', 'months'):
        days = number * 30
        return datetime.timedelta(days=days)
    if unit in ('year', 'years'):
        days = number * 365
        return datetime.timedelta(days=days)

    # For other units, use the appropriate keyword
    kwargs = {keyword: number}
    return datetime.timedelta(**kwargs)

