def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Validate matcher
    if matcher is None:
        raise ValueError("Matcher cannot be None")

    # Extract name and default from matcher
    if hasattr(matcher, 'group'):  # likely a regex match object
        try:
            name = matcher.group(1)
        except IndexError:
            raise ValueError("Matcher does not contain a variable name")
        default = None
        if matcher.lastindex and matcher.lastindex >= 2:
            try:
                default = matcher.group(2)
            except IndexError:
                default = None
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) == 0:
            raise ValueError("Matcher tuple/list must contain at least the variable name")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        raise ValueError(f"Unsupported matcher type: {type(matcher).__name__}")

    if name is None:
        raise ValueError("Variable name cannot be None")
    name = str(name)

    # Resolve environment variable
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return str(default)
    raise KeyError(f"Environment variable '{name}' not found and no default provided")

