def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if isinstance(commands, str):
        cmd = commands.split()
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if args is not None:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list/tuple of strings or None")
        cmd += list(args)

    if not cmd:
        raise ValueError("No command specified")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string path or None")

    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a bool")

    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a bool")

    if verbose:
        print("Running command:", " ".join(cmd))

    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}"
        ) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command '{' '.join(cmd)}': {e}") from e

