def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging
    import os
    import sys

    config_dict = {}
    error_records = []
    logger = logging.getLogger('config_loader')

    for filename in config_filenames:
        try:
            # Determine file format based on extension
            ext = os.path.splitext(filename)[1].lower()
            parsed = None

            if ext == '.json':
                import json
                with open(filename, 'r', encoding='utf-8') as f:
                    parsed = json.load(f)
            elif ext in ('.yaml', '.yml'):
                try:
                    import yaml
                except ImportError as e:
                    raise ImportError(f"YAML support not available for file {filename}") from e
                with open(filename, 'r', encoding='utf-8') as f:
                    parsed = yaml.safe_load(f)
            elif ext == '.ini':
                import configparser
                parser = configparser.ConfigParser()
                parser.read(filename, encoding='utf-8')
                parsed = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                # Default to JSON if unknown extension
                import json
                with open(filename, 'r', encoding='utf-8') as f:
                    parsed = json.load(f)

            if not isinstance(parsed, dict):
                raise ValueError(f"Configuration in {filename} is not a dictionary")

            # Apply overrides if provided
            if overrides:
                if not isinstance(overrides, dict):
                    raise TypeError("overrides must be a dict")
                parsed.update(overrides)

            # Resolve environment variables in string values
            if resolve_env:
                def resolve_value(val):
                    if isinstance(val, str):
                        return os.path.expandvars(val)
                    return val

                def recurse_dict(d):
                    for k, v in d.items():
                        if isinstance(v, dict):
                            recurse_dict(v)
                        else:
                            d[k] = resolve_value(v)

                recurse_dict(parsed)

            config_dict[filename] = parsed

        except Exception as e:
            # Create a LogRecord for the error
            exc_info = sys.exc_info()
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)

    return config_dict, error_records

