def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("__metaclass__ must be a class")
        for base in bases:
            if not issubclass(explicit_mc, type(base)):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc.__name__} is not a subclass of {type(base).__name__}"
                )
        return explicit_mc

    # No explicit metaclass: determine from bases
    if not bases:
        return type

    metaclasses = [type(b) for b in bases]

    # Find the most derived metaclass that is a subclass of all others
    for candidate in metaclasses:
        if all(issubclass(candidate, other) for other in metaclasses):
            return candidate

    # No common metaclass found
    names = ", ".join(mc.__name__ for mc in metaclasses)
    raise TypeError(f"metaclass conflict: {names}")

