def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem from an empty container')
    freq = getattr(self, 'freq', None)
    if freq is None:
        raise AttributeError('Container does not support frequency tracking')
    try:
        min_key = min(self, key=lambda k: freq.get(k, 0))
    except Exception as exc:
        raise RuntimeError('Failed to determine least frequently used key') from exc
    try:
        value = self.pop(min_key)
    except KeyError as exc:
        raise KeyError(f'Key {min_key!r} not found during popitem') from exc
    freq.pop(min_key, None)
    return (min_key, value)

