        # Check for private message
        if hasattr(request, 'private_message') and request.private_message:
            return True

        # Check for legacy payload
        if hasattr(request, 'legacy_payload') and request.legacy_payload:
            return True

        # If request is dict-like
        if isinstance(request, dict):
            if request.get('public') or request.get('private') or request.get('legacy'):
                return True

        # If request has a json() method
        if hasattr(request, 'json') and callable(request.json):
            data = request.json()
            if isinstance(data, dict):
                if data.get('public') or data.get('private') or data.get('legacy'):
                    return True

        # If request has a data attribute
        if hasattr(request, 'data'):
            data = request.data
            if isinstance(data, dict):
                if data.get('public') or data.get('private') or data.get('legacy'):
