def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    import datetime
    if dt is None:
        raise ValueError("dt cannot be None")
    if isinstance(dt, datetime.date) and not isinstance(dt, datetime.datetime):
        # plain date
        return dt.strftime("%Y-%m-%d")
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime or datetime.date instance")
    # Remove microseconds for consistency
    dt = dt.replace(microsecond=0)
    if dt.tzinfo is None:
        # naive datetime: no timezone information
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    # timezone-aware: use ISO 8601 with offset
    return dt.isoformat()

