def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json
    from urllib.error import URLError, HTTPError

    if not isinstance(handle, str):
        raise ValueError("Handle must be a string")

    # Strip optional 'acct:' prefix
    if handle.lower().startswith("acct:"):
        handle = handle[5:]

    if "@" not in handle:
        raise ValueError("Handle must be in the form 'user@domain'")

    localpart, domain = handle.split("@", 1)
    if not localpart or not domain:
        raise ValueError("Handle must contain both user and domain parts")

    resource = f"acct:{handle}"
    query = urllib.parse.urlencode({"resource": resource})
    url = f"https://{domain}/.well-known/webfinger?{query}"

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                raise ValueError(f"HTTP error {response.status} when retrieving webfinger for {handle}")
            data_bytes = response.read()
            data_str = data_bytes.decode("utf-8")
            try:
                data = json.loads(data_str)
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON from webfinger response for {handle}: {e}") from e
            return data
    except HTTPError as e:
        raise ValueError(f"HTTP error {e.code} when retrieving webfinger for {handle}") from e
