def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")

    resolved_cache = {}

    def resolve(name, stack):
        if name in resolved_cache:
            return resolved_cache[name]
        if name in stack:
            raise ValueError(
                f"Circular include detected: {' -> '.join(stack + [name])}"
            )
        if name not in parser_dict:
            raise KeyError(f"Included group '{name}' not found in parser_dict")
        group = parser_dict[name]
        if not isinstance(group, dict):
            raise TypeError(f"Group '{name}' must be a dict")

        result = {}
        includes = group.get("include")
        if includes:
            if isinstance(includes, str):
                includes = [includes]
            if not isinstance(includes, (list, tuple)):
                raise TypeError(
                    f"Include directive in group '{name}' must be a string or list"
                )
            for inc in includes:
                inc_resolved = resolve(inc, stack + [name])
                result.update(inc_resolved)

        for k, v in group.items():
            if k != "include":
                result[k] = v

        resolved_cache[name] = result
        return result

    for key in list(parser_dict.keys()):
        parser_dict[key] = resolve(key, [])

    return parser_dict

