def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict

        # If extra_vars is a dict, update directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # If it's an iterable (list/tuple), iterate over items
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be a dict or an iterable of key/value pairs")

        for item in iterator:
            # If item is a dict, update
            if isinstance(item, dict):
                vars_dict.update(item)
                continue
            # If item is a tuple/list of length 2, treat as key/value
            if isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                vars_dict[key] = value
                continue
            # If item is a string of form "key=value"
            if isinstance(item, str):
                if '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key] = value
                    continue
