def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import shlex

    # Validate playbook_path
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")

    # Base command
    cmd = ['ansible-playbook', playbook_path]

    # Verbosity
    if verbose is not None:
        if not isinstance(verbose, int):
            raise TypeError("verbose must be an integer")
        if verbose > 0:
            cmd.append('-' + 'v' * verbose)

    # Extra vars
    if extra_vars is not None:
        if isinstance(extra_vars, dict):
            extra_str = json.dumps(extra_vars)
        elif isinstance(extra_vars, str):
            extra_str = extra_vars
        else:
            raise TypeError("extra_vars must be a dict or a string")
        cmd.extend(['--extra-vars', extra_str])

    # Additional ansible arguments
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not key.startswith('--'):
                key = '--' + key
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
                # skip if False
            else:
                cmd.extend([key, str(value)])

    # Optional logging
    logger = getattr(ir_plugin, 'logger', None)
    if logger:
        logger.debug(f"Running ansible-playbook: {' '.join(shlex.quote(c) for c in cmd)}")

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        if logger:
            logger.error(f"ansible-playbook failed with exit code {e.returncode}")
            logger.error(f"stderr: {e.stderr}")
        raise
    except FileNotFoundError:
        if logger:
            logger.error("ansible-playbook executable not found")
        raise

    return result

