def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json
    import os

    # Basic type checks
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list of strings")
    if not all(isinstance(arg, str) for arg in cli_args):
        raise TypeError("All elements of cli_args must be strings")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not hasattr(ir_workspace, "path"):
        raise AttributeError("ir_workspace must have a 'path' attribute")
    if not isinstance(ir_workspace.path, str):
        raise TypeError("ir_workspace.path must be a string")
    if not os.path.isdir(ir_workspace.path):
        raise FileNotFoundError(f"Workspace path '{ir_workspace.path}' does not exist or is not a directory")
    if not hasattr(ir_plugin, "log"):
        raise AttributeError("ir_plugin must have a 'log' method")
    # Optional: log error method
    log_error = getattr(ir_plugin, "log_error", None)

    # Build the ansible command
    cmd = ["ansible-playbook"] + cli_args + ["--extra-vars", json.dumps(vars_dict)]
    ir_plugin.log(f"Running ansible command: {' '.join(cmd)} in {ir_workspace.path}")

    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as e:
        msg = "ansible-playbook not found. Ensure Ansible is installed and in PATH."
        if log_error:
            ir_plugin.log_error(msg)
        raise RuntimeError(msg) from e
    except Exception as e:
        msg = f"Error running ansible: {e}"
        if log_error:
            ir_plugin.log_error(msg)
        raise RuntimeError(msg) from e

    # Log if the playbook failed
    if result.returncode != 0:
        err_msg = f"Ansible playbook failed with return code {result.returncode}"
        if log_error:
            ir_plugin.log_error(err_msg)
        else:
            ir_plugin.log(err_msg)

    # Return a dictionary with the results
    return {
        "returncode": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr,
    }

