def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        # locate the spec file
        spec_file = None
        for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
            path = os.path.join(plugin_dir, fname)
            if os.path.isfile(path):
                spec_file = path
                break
        if not spec_file:
            raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

        # load the spec
        if spec_file.endswith(".json"):
            with open(spec_file, "r", encoding="utf-8") as f:
                data = json.load(f)
        else:
            # yaml support
            try:
                import yaml
            except ImportError as exc:
                raise RuntimeError("YAML support is required to read plugin spec") from exc
            with open(spec_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)

        # flatten nested structures
        flat = {}

        def _flatten(obj, prefix=""):
            if isinstance(obj, dict):
                for k, v in obj.items():
                    new_prefix = f"{prefix}.{k}" if prefix else k
                    _flatten(v, new_prefix)
            elif isinstance(obj, list):
                for i, item in enumerate(obj):
                    new_prefix = f"{prefix}[{i}]" if prefix else f"[{i}]"
                    _flatten(item, new_prefix)
            else:
                flat[prefix] = obj

        _flatten(data)
        return flat
    except Exception as exc:
        raise RuntimeError(f"Failed to read plugin spec from {plugin_dir}: {exc}") from exc

